// All symbols below were verified by javap/decompile in this run.
// Placing a block without going through the private Minecraft.startUseItem().
import net.minecraft.client.Minecraft;
import net.minecraft.client.player.LocalPlayer;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.phys.BlockHitResult;
import net.minecraft.world.phys.Vec3;
import net.minecraft.world.inventory.ContainerInput;

void placeAt(int hotbarSlot, BlockPos target, Direction face, Vec3 hitVec) {
    Minecraft mc = Minecraft.getInstance();
    LocalPlayer player = mc.player;
    if (player == null || mc.level == null || mc.gameMode == null) return;

    // Own throttle: nothing in MultiPlayerGameMode rate-limits useItemOn,
    // and Minecraft.rightClickDelay is private and never consulted here.
    if (mc.gameMode.isDestroying()) return;
    if (player.isHandsBusy()) return;

    // Switch through the inventory so the private ensureHasSentCarriedItem()
    // at the top of useItemOn emits ServerboundSetCarriedItemPacket first.
    player.getInventory().setSelectedSlot(hotbarSlot);

    // useItemOn checks the world border only; it does NO reach check.
    // Mirror the server's own predicate so we do not send a silently-dropped packet.
    if (!player.isWithinBlockInteractionRange(target, 1.0)) return;
    if (!mc.level.getWorldBorder().isWithinBounds(target)) return;

    BlockHitResult hit = new BlockHitResult(hitVec, face, target, false);

    // No sequence argument: useItemOn allocates it via startPrediction and
    // builds ServerboundUseItemOnPacket(hand, blockHit, sequence) internally.
    InteractionResult result = mc.gameMode.useItemOn(player, InteractionHand.MAIN_HAND, hit);

    if (result instanceof InteractionResult.Success success) {
        // useItemOn never swings; and only swing when the client owns it,
        // otherwise the server's own player.swing(hand, true) double-swings.
        if (success.swingSource() == InteractionResult.SwingSource.CLIENT) {
            player.swing(InteractionHand.MAIN_HAND);
        }
    } else if (result instanceof InteractionResult.Fail) {
        // outside the world border, or the block's feature flag is disabled
    }
}

// Hotbar-swap style container click (26.2 rename of handleInventoryMouseClick/ClickType).
void swapWithHotbar(int slotIndex, int hotbarIndex) {
    Minecraft mc = Minecraft.getInstance();
    LocalPlayer player = mc.player;
    if (player == null || mc.gameMode == null) return;
    // buttonNum 0..8 = hotbar index, 40 = offhand.
    mc.gameMode.handleContainerInput(
        player.containerMenu.containerId, slotIndex, hotbarIndex, ContainerInput.SWAP, player);
}
